        // \u8C03\u7528\u771F\u5B9E\u7684\u6E05\u7406\u7F13\u5B58API
        const response = await fetch(buildApiUrl('/api/cache/clear', true), { // \u4F7F\u7528admin token
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({})
        });

